from taf.rfrl.procedures.resources.python.status_check.rmod.Rmod import Rmod


class RanEcpriRmod(Rmod):

    def _get_active_statuses(self):
        return {"operationalState": self._status_selector.select_operational_state(variant='enabled'),
                "administrativeState": self._status_selector.select_administrative_state(variant='unlocked'),
                "availabilityStatus": self._status_selector.select_availability_status(variant='online'),
                "usageState": "Active",
                "proceduralStatus": "configured"}

    def _get_online_statuses(self):
        return {"operationalState": self._status_selector.select_operational_state(variant='enabled'),
                "administrativeState": self._status_selector.select_administrative_state(variant='unlocked'),
                "availabilityStatus": self._status_selector.select_availability_status(variant='online'),
                "proceduralStatus": "configured"}

    def _get_offline_statuses(self):
        return {"operationalState": self._status_selector.select_operational_state(variant='disabled'),
                "administrativeState": self._status_selector.select_administrative_state(variant='unlocked'),
                "usageState": "Idle",
                "proceduralStatus": "initializing",
                "availabilityStatus": self._status_selector.select_availability_status(variant='offline')}

    def _get_disabled_statuses(self):
        return {"operationalState": self._status_selector.select_operational_state(variant='disabled'),
                "administrativeState": self._status_selector.select_administrative_state(variant='unlocked'),
                "usageState": "Idle",
                "proceduralStatus": "not initialized",
                "availabilityStatus": self._status_selector.select_availability_status(variant='not_installed')}

    def _get_locked_statuses(self):
        return {"operationalState": self._status_selector.select_operational_state(variant='enabled'),
                "administrativeState": self._status_selector.select_administrative_state(variant='locked'),
                "usageState": "Idle",
                "proceduralStatus": "configured"}

    def _get_failed_statuses(self):
        return {"operationalState": self._status_selector.select_operational_state(variant='disabled'),
                "administrativeState": self._status_selector.select_administrative_state(variant='unlocked'),
                "usageState": "Idle",
                "availabilityStatus": "failed"}

    def _get_deep_sleep_statuses(self):
        return {"operationalState": self._status_selector.select_operational_state(variant='enabled'),
                "administrativeState": self._status_selector.select_administrative_state(variant='unlocked'),
                "usageState": "Idle",
                "proceduralStatus": "configured",
                "powerState": "SLEEP"}

    def _get_extreme_deep_sleep_statuses(self):
        return {"operationalState": self._status_selector.select_operational_state(variant='enabled'),
                "administrativeState": self._status_selector.select_administrative_state(variant='unlocked'),
                "usageState": "Idle",
                "proceduralStatus": "configured",
                "powerState": "SLEEP_EXTREME"}
